import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import {
  Box, Typography, Paper, Table, TableBody, TableCell, TableContainer,
  TableHead, TableRow, TextField, Button, CircularProgress, TablePagination,
  FormControl, InputLabel, Select, MenuItem, Grid
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import DownloadIcon from '@mui/icons-material/Download';

const PhonebookPage = () => {
  const { t } = useTranslation();
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(50);
  const [search, setSearch] = useState('');
  const [department, setDepartment] = useState('');

  const { data, isLoading } = useQuery({
    queryKey: ['phonebook', page, rowsPerPage, search, department],
    queryFn: () => axiosInstance.get('/phonebook/', {
      params: { page: page + 1, page_size: rowsPerPage, search: search || undefined, department: department || undefined }
    }).then(r => r.data),
  });

  const employees = data?.results || [];
  const totalCount = data?.count || 0;

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h4">{t('phonebook.title')}</Typography>
        <Button variant="outlined" startIcon={<DownloadIcon />}
          component="a" href={`${axiosInstance.defaults.baseURL}/phonebook/export/`}
          target="_blank">
          {t('phonebook.export_excel')}
        </Button>
      </Box>
      <Paper sx={{ p: 2, mb: 2 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={6}>
            <TextField fullWidth size="small" placeholder={t('common.search')}
              value={search} onChange={e => setSearch(e.target.value)}
              InputProps={{ startAdornment: <SearchIcon sx={{ mr: 1, color: 'gray' }} /> }} />
          </Grid>
          <Grid item xs={12} md={4}>
            <FormControl fullWidth size="small">
              <InputLabel>{t('employees.department')}</InputLabel>
              <Select value={department} label={t('employees.department')}
                onChange={e => setDepartment(e.target.value)}>
                <MenuItem value="">{t('common.all')}</MenuItem>
              </Select>
            </FormControl>
          </Grid>
        </Grid>
      </Paper>
      <TableContainer component={Paper}>
        {isLoading ? <Box sx={{ p: 4, textAlign: 'center' }}><CircularProgress /></Box> : (
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>{t('employees.employee_id')}</TableCell>
                <TableCell>{t('employees.full_name')}</TableCell>
                <TableCell>{t('employees.mobile')}</TableCell>
                <TableCell>{t('employees.phone')}</TableCell>
                <TableCell>{t('employees.department')}</TableCell>
                <TableCell>{t('employees.job_title')}</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {employees.map(emp => (
                <TableRow key={emp.id} hover>
                  <TableCell>{emp.employee_id}</TableCell>
                  <TableCell>{emp.full_name}</TableCell>
                  <TableCell><a href={`tel:${emp.mobile}`}>{emp.mobile}</a></TableCell>
                  <TableCell>{emp.phone || '—'}</TableCell>
                  <TableCell>{emp.department}</TableCell>
                  <TableCell>{emp.job_title}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
        <TablePagination component="div" count={totalCount} page={page}
          onPageChange={(e, p) => setPage(p)} rowsPerPage={rowsPerPage}
          onRowsPerPageChange={e => { setRowsPerPage(Number(e.target.value)); setPage(0); }} />
      </TableContainer>
    </Box>
  );
};

export default PhonebookPage;
